function renderArchitectureDiagram(lines, projectName, subsystems, databases, externalServices, files, routes, deployment) {
    const skipNames = new Set(['root', 'src', 'test', 'tests']);
    const relevantSubs = subsystems.filter(s => !skipNames.has(s.name.toLowerCase()) && !s.name.startsWith('('));
    // Build inter-module dependency map from actual imports
    const fileToModule = new Map();
    for (const sub of relevantSubs) {
        for (const f of sub.files) {
            fileToModule.set(f, sub.name);
        }
    }
    const moduleDeps = new Map();
    for (const sub of relevantSubs) {
        moduleDeps.set(sub.name, new Set());
        for (const f of sub.files) {
            const node = files.get(f);
            if (!node)
                continue;
            for (const imp of node.imports) {
                const target = fileToModule.get(imp);
                if (target && target !== sub.name) {
                    moduleDeps.get(sub.name).add(target);
                }
            }
        }
    }
    // Group subsystems into layers
    const uiModules = relevantSubs.filter(s => ['components', 'pages', 'views', 'layouts', 'ui', 'app', 'static', 'frontend', 'client'].includes(s.name.toLowerCase()));
    const dataModules = relevantSubs.filter(s => ['models', 'schemas', 'entities', 'database', 'db', 'mongo', 'prisma', 'migrations', 'repositories'].includes(s.name.toLowerCase()));
    const infraModules = relevantSubs.filter(s => ['common', 'shared', 'utils', 'helpers', 'config', 'health', 'middleware'].includes(s.name.toLowerCase()));
    const featureModules = relevantSubs.filter(s => !uiModules.includes(s) && !dataModules.includes(s) && !infraModules.includes(s));
    lines.push('```mermaid');
    lines.push('flowchart TB');
    // Client
    lines.push('  CLIENT([Client])');
    // UI Layer
    if (uiModules.length > 0) {
        lines.push('  subgraph UI["Presentation"]');
        for (const sub of uiModules) {
            lines.push(`    ${sanitizeId(sub.name)}["${sanitizeMermaid(sub.name)}"]`);
        }
        lines.push('  end');
    }
    // Feature Modules Layer
    if (featureModules.length > 0) {
        lines.push('  subgraph FEATURES["Feature Modules"]');
        for (const sub of featureModules) {
            const moduleRoutes = routes.filter(r => sub.files.includes(r.file) && r.method !== 'USE');
            const label = moduleRoutes.length > 0
                ? `${sub.name}\\n${moduleRoutes.length} endpoints`
                : sub.name;
            lines.push(`    ${sanitizeId(sub.name)}["${sanitizeMermaid(label)}"]`);
        }
        lines.push('  end');
    }
    // Shared/Infra Layer
    if (infraModules.length > 0) {
        lines.push('  subgraph SHARED["Shared"]');
        for (const sub of infraModules) {
            lines.push(`    ${sanitizeId(sub.name)}["${sanitizeMermaid(sub.name)}"]`);
        }
        lines.push('  end');
    }
    // Data Layer
    if (dataModules.length > 0) {
        lines.push('  subgraph DATA["Data Layer"]');
        for (const sub of dataModules) {
            lines.push(`    ${sanitizeId(sub.name)}["${sanitizeMermaid(sub.name)}"]`);
        }
        lines.push('  end');
    }
    // External systems
    if (databases.length > 0) {
        for (const db of databases) {
            lines.push(`  DB[("${formatDbType(db.type)}")]`);
        }
    }
    if (externalServices.length > 0) {
        lines.push('  subgraph EXT["External Services"]');
        const uniqueServices = new Set();
        for (const svc of externalServices.slice(0, 8)) {
            if (uniqueServices.has(svc.label))
                continue;
            uniqueServices.add(svc.label);
            lines.push(`    ext_${sanitizeId(svc.label)}>"${sanitizeMermaid(svc.label)}"]`);
        }
        lines.push('  end');
    }
    // Client connections
    if (uiModules.length > 0) {
        lines.push(`  CLIENT --> UI`);
    }
    else if (featureModules.length > 0) {
        lines.push(`  CLIENT --> FEATURES`);
    }
    // Render actual inter-module dependencies (only significant ones)
    const renderedEdges = new Set();
    for (const [mod, deps] of moduleDeps) {
        for (const dep of deps) {
            const edgeKey = `${sanitizeId(mod)}-${sanitizeId(dep)}`;
            if (renderedEdges.has(edgeKey))
                continue;
            renderedEdges.add(edgeKey);
            // Only show edges between modules that are both in our relevant set
            if (relevantSubs.some(s => s.name === mod) && relevantSubs.some(s => s.name === dep)) {
                lines.push(`  ${sanitizeId(mod)} --> ${sanitizeId(dep)}`);
            }
        }
    }
    // Data layer to DB
    if (dataModules.length > 0 && databases.length > 0) {
        lines.push(`  ${sanitizeId(dataModules[0].name)} --> DB`);
    }
    else if (databases.length > 0) {
        // Find modules that import from schema/data modules
        const dbUsers = relevantSubs.filter(s => {
            const deps = moduleDeps.get(s.name) || new Set();
            return [...deps].some(d => dataModules.some(dm => dm.name === d));
        });
        if (dbUsers.length === 0 && featureModules.length > 0) {
            lines.push(`  FEATURES --> DB`);
        }
    }
    // External service connections — find which modules actually use them
    if (externalServices.length > 0) {
        const extFiles = new Set(externalServices.flatMap(s => s.files));
        const extModules = relevantSubs.filter(s => s.files.some(f => extFiles.has(f)));
        if (extModules.length > 0) {
            for (const em of extModules.slice(0, 3)) {
                lines.push(`  ${sanitizeId(em.name)} --> EXT`);
            }
        }
        else {
            lines.push(`  FEATURES --> EXT`);
        }
    }
    lines.push('```');
    lines.push('');
}
