    const entries = [...tree.entries()].sort((a, b) => b[1].loc - a[1].loc);
    for (const [name, info] of entries) {
        if (info.subFiles.length === 0)
            continue;
        // Find the shortest (common) directory path across all files in this module
        const dirPaths = info.subFiles.map(f => {
            const parts = f.split('/');
            parts.pop(); // remove filename
            return parts;
        });
        // Find common prefix
        const common = dirPaths[0] || [];
        let prefixLen = common.length;
        for (let i = 1; i < dirPaths.length; i++) {
            const p = dirPaths[i];
            let j = 0;
            while (j < prefixLen && j < p.length && common[j] === p[j])
                j++;
            prefixLen = j;
        }
        const parts = common.slice(0, prefixLen);
        let current = root;
        for (const part of parts) {
            if (!current.children.has(part)) {
                current.children.set(part, { children: new Map() });
            }
            current = current.children.get(part);
        }
        current.info = { files: info.files, loc: info.loc, description: info.description };
    }
