    const hasService = fileNames.some(f => f.includes('service'));
    const hasSchema = fileNames.some(f => f.includes('schema') || f.includes('model') || f.includes('entity'));
    // Specific known patterns
    const purposeMap = {
        auth: 'Authentication & authorization',
        guard: 'Route guards & access control',
        guards: 'Route guards & access control',
        schemas: 'Database models & schemas',
        models: 'Data models',
        entities: 'Database entities',
        common: 'Shared utilities & helpers',
        shared: 'Shared code across modules',
        utils: 'Utility functions',
        config: 'App configuration',
        middleware: 'Request middleware',
        integrations: 'External service integrations',
        mongo: 'Database connection setup',
        prisma: 'Database ORM setup',
        health: 'Health check endpoints',
        src: 'Application source root',
        root: 'Project root files',
    };
    for (const [key, desc] of Object.entries(purposeMap)) {
        if (name === key || name === key + 's')
            return desc;
    }
    // Infer from file patterns
    if (hasController && hasService)
        return 'Feature module (API + business logic)';
    if (hasController)
        return 'API controllers';
    if (hasService)
        return 'Business logic / services';
    if (hasSchema)
        return 'Data models';
