// ─── Usage Examples Section ───
function renderUsageExamples(lines, routes, projectName) {
    // Filter to real endpoints (not test files)
    const isTestFile = (f) => /\.(spec|test|e2e-spec)\b/.test(f) || /\btest[s]?\//.test(f) || /\b__tests__\//.test(f);
    const endpoints = routes.filter(r => r.method !== 'USE' && !isTestFile(r.file));
    if (endpoints.length === 0)
        return;
    lines.push('> Example API calls for key endpoints. Replace `localhost:3000` with your actual host.');
    lines.push('');
    // Pick representative endpoints: one GET, one POST, one with params
    const examples = [];
    const seen = new Set();
    // Health check first
    const health = endpoints.find(r => r.method === 'GET' && (r.path.includes('health') || r.path === '/'));
    if (health) {
        examples.push(health);
        seen.add(`${health.method}:${health.path}`);
    }
    // One GET with path params
    const getWithParams = endpoints.find(r => r.method === 'GET' && r.path.includes(':') && !seen.has(`${r.method}:${r.path}`));
    if (getWithParams) {
        examples.push(getWithParams);
        seen.add(`${getWithParams.method}:${getWithParams.path}`);
    }
    // One GET list
    const getList = endpoints.find(r => r.method === 'GET' && !r.path.includes(':') && r.path !== '/' && !r.path.includes('health') && !seen.has(`${r.method}:${r.path}`));
    if (getList) {
        examples.push(getList);
        seen.add(`${getList.method}:${getList.path}`);
    }
    // One POST
    const post = endpoints.find(r => r.method === 'POST' && !seen.has(`${r.method}:${r.path}`));
    if (post) {
        examples.push(post);
        seen.add(`${post.method}:${post.path}`);
    }
    // One PUT/PATCH
    const update = endpoints.find(r => (r.method === 'PUT' || r.method === 'PATCH') && !seen.has(`${r.method}:${r.path}`));
    if (update) {
        examples.push(update);
        seen.add(`${update.method}:${update.path}`);
    }
    // One DELETE
    const del = endpoints.find(r => r.method === 'DELETE' && !seen.has(`${r.method}:${r.path}`));
    if (del) {
        examples.push(del);
        seen.add(`${del.method}:${del.path}`);
    }
    if (examples.length === 0)
        return;
    lines.push('```bash');
    for (let i = 0; i < examples.length; i++) {
        const r = examples[i];
        const path = r.path.replace(/:(\w+)/g, '{$1}');
        if (i > 0)
            lines.push('');
        lines.push(`# ${r.handler || r.method + ' ' + r.path}`);
        if (r.method === 'GET' || r.method === 'DELETE') {
            lines.push(`curl -X ${r.method} http://localhost:3000${path}`);
        }
        else {
            lines.push(`curl -X ${r.method} http://localhost:3000${path} \\`);
            lines.push(`  -H "Content-Type: application/json" \\`);
            lines.push(`  -d '{ }'`);
        }
    }
    lines.push('```');
    lines.push('');
}
