function renderLifecycleEvents(lines, events) {
    lines.push('## Lifecycle');
    lines.push('');
    lines.push('Things that happen when the app boots, when requests arrive, and when external systems trigger us.');
    lines.push('');
    // Group by kind for readability
    const order = [
        'app-boot', 'request-flow', 'install', 'uninstall', 'webhook', 'scheduled', 'event-emitter',
    ];
    const byKind = new Map();
    for (const e of events) {
        if (!byKind.has(e.kind))
            byKind.set(e.kind, []);
        byKind.get(e.kind).push(e);
    }
    for (const kind of order) {
        const items = byKind.get(kind);
        if (!items || items.length === 0)
            continue;
        lines.push(`**${lifecycleKindLabel(kind)}**`);
        lines.push('');
        for (const item of items) {
            const handler = item.handler ? ` — \`${item.handler}\`` : '';
            lines.push(`- ${item.description} (trigger: \`${item.trigger}\`)${handler}`);
        }
        lines.push('');
    }
}
function lifecycleKindLabel(kind) {
    switch (kind) {
        case 'app-boot': return 'On boot';
        case 'request-flow': return 'Per request';
        case 'install': return 'On install';
        case 'uninstall': return 'On uninstall';
        case 'webhook': return 'Inbound webhooks';
        case 'scheduled': return 'Scheduled jobs';
        case 'event-emitter': return 'In-process events';
        default: return kind;
    }
}
